        ('EQ-COMP', 'Capacity Control', 'COMP.VALV.SOL', 'Resistance (isolated)', 'Ω / mΩ', 'Micro-ohmmeter / multimeter (isolated)', 'Per OEM / site procedure (measurement point to be marked on equipment)', 'OEM specification or approved site baseline required - no universal threshold given (model-specific verification required)', 'Applies to CASE-COMP-015 (synthetic); conditions: same load/speed as baseline', 'Workbook source note: No OEM/standard threshold located; see S03/S07 for method only. Source reliability: D (method sources: A, not inspected). No numerical limit supplied: taking a limit from this sheet would be wrong; use OEM manual or approved site baseline.'),
        ('EQ-COMP', 'Capacity Control', 'COMP.VALV.SOL', 'Control air', 'Per instrument', 'Instrument to be selected by qualified person', 'Per OEM / site procedure (measurement point to be marked on equipment)', 'OEM specification or approved site baseline required - no universal threshold given (model-specific verification required)', 'Applies to CASE-COMP-015 (synthetic); conditions: same load/speed as baseline', 'Workbook source note: No OEM/standard threshold located; see S03/S07 for method only. Source reliability: D (method sources: A, not inspected). No numerical limit supplied: taking a limit from this sheet would be wrong; use OEM manual or approved site baseline.'),
        ('EQ-COMP', 'Controls/instrumentation (no FMEA_Taxonomy row)', NULL, 'Reference pressure', 'bar or kPa (per gauge)', 'Calibrated gauge', 'Per OEM / site procedure (measurement point to be marked on equipment)', 'OEM specification or approved site baseline required - no universal threshold given (model-specific verification required)', 'Applies to CASE-COMP-016 (synthetic); conditions: same load/speed as baseline', 'Workbook source note: No OEM/standard threshold located; see S03/S07 for method only. Source reliability: D (method sources: A, not inspected). No numerical limit supplied: taking a limit from this sheet would be wrong; use OEM manual or approved site baseline.'),
        ('EQ-COMP', 'Controls/instrumentation (no FMEA_Taxonomy row)', NULL, 'Signal', 'Per instrument', 'Meter', 'Per OEM / site procedure (measurement point to be marked on equipment)', 'OEM specification or approved site baseline required - no universal threshold given (model-specific verification required)', 'Applies to CASE-COMP-016 (synthetic); conditions: same load/speed as baseline', 'Workbook source note: No OEM/standard threshold located; see S03/S07 for method only. Source reliability: D (method sources: A, not inspected). No numerical limit supplied: taking a limit from this sheet would be wrong; use OEM manual or approved site baseline.'),
        ('EQ-COMP', 'Controls/instrumentation (no FMEA_Taxonomy row)', NULL, 'Trend', 'Per instrument', 'Instrument to be selected by qualified person', 'Per OEM / site procedure (measurement point to be marked on equipment)', 'OEM specification or approved site baseline required - no universal threshold given (model-specific verification required)', 'Applies to CASE-COMP-016 (synthetic); conditions: same load/speed as baseline', 'Workbook source note: No OEM/standard threshold located; see S03/S07 for method only. Source reliability: D (method sources: A, not inspected). No numerical limit supplied: taking a limit from this sheet would be wrong; use OEM manual or approved site baseline.')
),
resolved AS (
    SELECT
        i.equipment_class_id,
        s.subsystem_id,
        i.taxonomy_code,
        i.parameter,
        i.unit,
        i.instrument,
        i.measurement_location,
        i.reference_value_policy,
        CASE
            WHEN s.subsystem_id IS NULL
            THEN 'Workbook subsystem label: ' || i.subsystem_name || '. ' || COALESCE(i.applicability_conditions, '')
            ELSE i.applicability_conditions
        END AS applicability_conditions,
        i.limitations
    FROM incoming i
    LEFT JOIN public.subsystem s
        ON s.subsystem_name = i.subsystem_name
)
INSERT INTO public.measurement_reference
    (equipment_class_id, subsystem_id, taxonomy_code, parameter, unit,
     instrument, measurement_location, reference_value_policy,
     applicability_conditions, limitations)
SELECT
    r.equipment_class_id,
    r.subsystem_id,
    r.taxonomy_code,
    r.parameter,
    r.unit,
    r.instrument,
    r.measurement_location,
    r.reference_value_policy,
    r.applicability_conditions,
    r.limitations
FROM resolved r
WHERE NOT EXISTS (
    SELECT 1
    FROM public.measurement_reference existing
    WHERE existing.equipment_class_id = r.equipment_class_id
      AND existing.parameter = r.parameter
      AND existing.measurement_location IS NOT DISTINCT FROM r.measurement_location
      AND existing.subsystem_id IS NOT DISTINCT FROM r.subsystem_id
      AND existing.taxonomy_code IS NOT DISTINCT FROM r.taxonomy_code
      AND existing.reference_value_policy IS NOT DISTINCT FROM r.reference_value_policy
);

SELECT COUNT(*) AS measurement_reference_total
FROM public.measurement_reference;

SELECT COUNT(*) AS rows_with_no_numeric_threshold
FROM public.measurement_reference
WHERE reference_value_policy ILIKE '%no universal threshold%'
   OR limitations ILIKE '%no numerical limit%';

COMMIT;
